import * as THREE from 'three';

export const TAU = Math.PI * 2;
export const clamp = (v, min, max) => Math.min(max, Math.max(min, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const randInt = (a, b) => Math.floor(rand(a, b + 1));
export const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

export function angleDiff(a, b) {
  let d = (b - a) % TAU;
  if (d > Math.PI) d -= TAU;
  if (d < -Math.PI) d += TAU;
  return d;
}
export function dampAngle(a, b, lambda, dt) {
  return a + angleDiff(a, b) * (1 - Math.exp(-lambda * dt));
}
export function mulberry32(seed) {
  let t = seed >>> 0;
  return function () {
    t += 0x6d2b79f5;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

export function makeCanvasTexture(w, h, draw, opts = {}) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const ctx = c.getContext('2d');
  draw(ctx, w, h);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  if (opts.repeat !== false) {
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
  }
  if (opts.anisotropy) tex.anisotropy = opts.anisotropy;
  tex.needsUpdate = true;
  return tex;
}

export function makeLabelSprite(text, opts = {}) {
  const {
    font = '700 44px "Barlow Condensed", sans-serif',
    color = '#ffffff',
    bg = 'rgba(8,10,14,0.82)',
    border = '#ffc531',
    padX = 30,
    padY = 16,
    scale = 1,
  } = opts;
  const c = document.createElement('canvas');
  const ctx = c.getContext('2d');
  ctx.font = font;
  const tw = Math.ceil(ctx.measureText(text).width);
  c.width = tw + padX * 2;
  c.height = 88 + padY * 2;
  const g = c.getContext('2d');
  g.font = font;
  g.fillStyle = bg;
  g.beginPath();
  const r = 10;
  const w = c.width;
  const h = c.height;
  g.moveTo(r, 0); g.lineTo(w - r, 0); g.quadraticCurveTo(w, 0, w, r);
  g.lineTo(w, h - r); g.quadraticCurveTo(w, h, w - r, h);
  g.lineTo(r, h); g.quadraticCurveTo(0, h, 0, h - r);
  g.lineTo(0, r); g.quadraticCurveTo(0, 0, r, 0);
  g.fill();
  g.strokeStyle = border;
  g.lineWidth = 5;
  g.stroke();
  g.fillStyle = color;
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.fillText(text, w / 2, h / 2 + 2);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: true, depthWrite: false });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set((w / h) * 2.2 * scale, 2.2 * scale, 1);
  return sprite;
}

export function disposeObject(obj) {
  obj.traverse((o) => {
    if (o.geometry) o.geometry.dispose();
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      for (const m of mats) {
        if (m.map) m.map.dispose();
        m.dispose();
      }
    }
  });
}

export function pointInRect(x, z, r, pad = 0) {
  return x > r.minX - pad && x < r.maxX + pad && z > r.minZ - pad && z < r.maxZ + pad;
}

export function circleRectResolve(pos, radius, rect) {
  const cx = clamp(pos.x, rect.minX, rect.maxX);
  const cz = clamp(pos.z, rect.minZ, rect.maxZ);
  let dx = pos.x - cx;
  let dz = pos.z - cz;
  const d2 = dx * dx + dz * dz;
  if (d2 > radius * radius) return false;
  if (d2 > 1e-8) {
    const d = Math.sqrt(d2);
    const push = radius - d;
    pos.x += (dx / d) * push;
    pos.z += (dz / d) * push;
  } else {
    // center is inside the rect: push out through the nearest side
    const left = Math.abs(pos.x - rect.minX);
    const right = Math.abs(rect.maxX - pos.x);
    const back = Math.abs(pos.z - rect.minZ);
    const front = Math.abs(rect.maxZ - pos.z);
    const m = Math.min(left, right, back, front);
    if (m === left) pos.x = rect.minX - radius;
    else if (m === right) pos.x = rect.maxX + radius;
    else if (m === back) pos.z = rect.minZ - radius;
    else pos.z = rect.maxZ + radius;
  }
  return true;
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { mulberry32, rand, pick, TAU, makeCanvasTexture } from './utils.js';

export const CITY = {
  lines: Array.from({ length: 10 }, (_, i) => -378 + i * 84),
  cell: 84,
  road: 18,
  block: 66,
  half: 378,
  playHalf: 370,
};

const PALETTES = [0xbf6b4f, 0xcfa87c, 0x8b9aa8, 0x9c7b8f, 0x7e957f, 0xc98a5e, 0x6f7f9c, 0xb0a08a];
const DISTRICTS = [
  'GANG SENGKETA', 'PASAR PAGI', 'TERMINAL TELUR',
  'KAMPUNG AYAM', 'KOTA TUA', 'BLOK JAGO',
  'PANTAI KREMES', 'BUKIT BULU', 'HUTAN BETIS',
];

const BILLBOARDS = [
  { x: -280, z: -168, ry: -Math.PI / 2, text: 'ROOSTER CITY', sub: 'SAN AYAM', bg: '#d8452e', fg: '#ffe9a8' },
  { x: 196, z: 210, ry: Math.PI / 2, text: 'AYAM GORENG', sub: 'PAK JAGO · 24 JAM', bg: '#f2c53d', fg: '#2a1608' },
  { x: -126, z: 280, ry: Math.PI, text: 'JANGAN RUSUH', sub: 'KOTA INI MILIK KITA', bg: '#1d2733', fg: '#ffc531' },
  { x: 42, z: -280, ry: 0, text: 'PISTOL?', sub: 'ILEGAL, TAPI SERU', bg: '#5a2c6e', fg: '#ffd8ff' },
  { x: 280, z: -42, ry: -Math.PI / 2, text: 'SAN AYAM', sub: 'KOTA TANPA TIDUR', bg: '#197a6a', fg: '#e7fff8' },
];

function makeFacadeTextures(seed, anisotropy) {
  const rng = mulberry32(seed);
  const lit = [];
  for (let i = 0; i < 16; i++) lit.push(rng() < 0.32);
  const facade = makeCanvasTexture(256, 256, (ctx, w, h) => {
    ctx.fillStyle = '#d8d2c4';
    ctx.fillRect(0, 0, w, h);
    for (let y = 0; y < 4; y++) {
      ctx.fillStyle = 'rgba(66,56,46,.20)';
      ctx.fillRect(0, y * 64 + 55, w, 4);
    }
    for (let y = 0; y < 4; y++) {
      for (let x = 0; x < 4; x++) {
        const px = x * 64 + 12;
        const py = y * 64 + 12;
        const on = lit[y * 4 + x];
        ctx.fillStyle = on ? '#ffe6ad' : '#26303d';
        ctx.fillRect(px, py, 40, 34);
        ctx.fillStyle = 'rgba(255,255,255,.12)';
        ctx.fillRect(px + 3, py + 3, 34, 8);
        ctx.strokeStyle = 'rgba(34,30,28,.55)';
        ctx.lineWidth = 2;
        ctx.strokeRect(px, py, 40, 34);
      }
    }
    ctx.fillStyle = 'rgba(255,255,255,.06)';
    ctx.fillRect(0, 0, 6, h);
  }, { anisotropy });
  const emissive = makeCanvasTexture(256, 256, (ctx, w, h) => {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, w, h);
    for (let y = 0; y < 4; y++) {
      for (let x = 0; x < 4; x++) {
        if (!lit[y * 4 + x]) continue;
        ctx.fillStyle = '#ffcf82';
        ctx.fillRect(x * 64 + 12, y * 64 + 12, 40, 34);
      }
    }
  }, { anisotropy });
  return { facade, emissive };
}

function windowBox(w, h, d) {
  const g = new THREE.BoxGeometry(w, h, d);
  const uv = g.attributes.uv;
  const faces = [
    [d, h], [d, h],
    [w, d], [w, d],
    [w, h], [w, h],
  ];
  for (let f = 0; f < 6; f++) {
    const uRep = Math.max(1, Math.round(faces[f][0] / 4.2));
    const vRep = Math.max(1, Math.round(faces[f][1] / 4.2));
    for (let i = f * 4; i < f * 4 + 4; i++) {
      uv.setXY(i, uv.getX(i) * uRep, uv.getY(i) * vRep);
    }
  }
  return g;
}

function makeSky(scene) {
  const geo = new THREE.SphereGeometry(1100, 32, 20);
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      top: { value: new THREE.Color(0x18365f) },
      mid: { value: new THREE.Color(0xd9774f) },
      bottom: { value: new THREE.Color(0xffc27a) },
      sunDir: { value: new THREE.Vector3(-0.52, 0.2, -0.72).normalize() },
    },
    vertexShader: `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 top; uniform vec3 mid; uniform vec3 bottom; uniform vec3 sunDir;
      varying vec3 vDir;
      void main() {
        vec3 d = normalize(vDir);
        float h = d.y;
        vec3 col = mix(bottom, mid, smoothstep(-0.02, 0.24, h));
        col = mix(col, top, smoothstep(0.2, 0.7, h));
        float sun = pow(max(dot(d, sunDir), 0.0), 320.0);
        float glow = pow(max(dot(d, sunDir), 0.0), 9.0);
        col += vec3(1.0, 0.82, 0.5) * sun * 1.5;
        col += vec3(1.0, 0.45, 0.18) * glow * 0.2;
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });
  const sky = new THREE.Mesh(geo, mat);
  sky.frustumCulled = false;
  sky.renderOrder = -100;
  scene.add(sky);

  // sun glow sprite
  const sunDir = mat.uniforms.sunDir.value;
  const sunTex = makeCanvasTexture(128, 128, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 2, w / 2, h / 2, w / 2);
    g.addColorStop(0, 'rgba(255,246,214,1)');
    g.addColorStop(0.22, 'rgba(255,213,140,.95)');
    g.addColorStop(0.55, 'rgba(255,150,70,.35)');
    g.addColorStop(1, 'rgba(255,120,40,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  }, { repeat: false });
  const sun = new THREE.Sprite(new THREE.SpriteMaterial({ map: sunTex, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, toneMapped: false }));
  sun.position.copy(sunDir).multiplyScalar(880);
  sun.scale.set(260, 260, 1);
  scene.add(sun);

  const sunDisc = new THREE.Mesh(
    new THREE.CircleGeometry(28, 32),
    new THREE.MeshBasicMaterial({ color: 0xfff3c4, toneMapped: false, fog: false })
  );
  sunDisc.position.copy(sunDir).multiplyScalar(840);
  sunDisc.lookAt(0, 0, 0);
  scene.add(sunDisc);
  return { sky, sun, sunDir };
}

function makeMountains(scene) {
  const rng = mulberry32(9137);
  const geos = [];
  for (let i = 0; i < 26; i++) {
    const a = (i / 26) * TAU + rng() * 0.16;
    const r = 620 + rng() * 190;
    const height = 55 + rng() * 130;
    const radius = 90 + rng() * 120;
    const g = new THREE.ConeGeometry(radius, height, 5, 1);
    g.translate(Math.cos(a) * r, height / 2 - 6, Math.sin(a) * r);
    geos.push(g);
  }
  const mesh = new THREE.Mesh(
    mergeGeometries(geos, false),
    new THREE.MeshStandardMaterial({ color: 0x5a4d69, roughness: 1, flatShading: true })
  );
  mesh.receiveShadow = false;
  mesh.castShadow = false;
  scene.add(mesh);
  return mesh;
}

function makePalmGeometry() {
  const trunk = new THREE.CylinderGeometry(0.16, 0.3, 5.2, 5);
  trunk.translate(0, 2.6, 0);
  const fronds = [];
  for (let i = 0; i < 7; i++) {
    const g = new THREE.ConeGeometry(0.62, 3.8, 4, 1);
    g.scale(1, 1, 0.32);
    g.translate(0, 1.9, 0);
    g.rotateZ(1.16);
    g.rotateY((i / 7) * TAU + 0.3);
    g.translate(0, 4.9, 0);
    fronds.push(g);
  }
  const leaves = mergeGeometries(fronds, false);
  return { trunk, leaves };
}

function makeBillboard(def, anisotropy) {
  const group = new THREE.Group();
  const tex = makeCanvasTexture(512, 224, (ctx, w, h) => {
    ctx.fillStyle = def.bg;
    ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = 'rgba(0,0,0,.18)';
    ctx.fillRect(0, h - 28, w, 28);
    ctx.fillStyle = def.fg;
    ctx.textAlign = 'center';
    ctx.font = '400 86px "Anton", Impact, sans-serif';
    ctx.fillText(def.text, w / 2, 108);
    ctx.font = '700 34px "Barlow Condensed", sans-serif';
    ctx.letterSpacing = '4px';
    ctx.fillText(def.sub, w / 2, 164);
    ctx.strokeStyle = 'rgba(255,255,255,.22)';
    ctx.lineWidth = 10;
    ctx.strokeRect(5, 5, w - 10, h - 10);
  }, { repeat: false, anisotropy });
  const panel = new THREE.Mesh(
    new THREE.PlaneGeometry(13, 5.7),
    new THREE.MeshBasicMaterial({ map: tex, toneMapped: false })
  );
  panel.position.y = 8.2;
  group.add(panel);
  const back = new THREE.Mesh(
    new THREE.BoxGeometry(13.2, 5.9, 0.25),
    new THREE.MeshStandardMaterial({ color: 0x2a2d33, roughness: 0.9 })
  );
  back.position.set(0, 8.2, -0.16);
  group.add(back);
  const postMat = new THREE.MeshStandardMaterial({ color: 0x4b4f57, roughness: 0.8, metalness: 0.3 });
  for (const sx of [-4.6, 4.6]) {
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.22, 8.4, 6), postMat);
    post.position.set(sx, 4.2, -0.4);
    post.castShadow = true;
    group.add(post);
  }
  group.position.set(def.x, 0, def.z);
  group.rotation.y = def.ry;
  return group;
}

export function buildWorld(scene, renderer) {
  const anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
  const colliders = [];
  const buildings = [];
  const solidMeshes = [];
  const sidewalkPoints = [];
  const carSpots = [];
  const intersections = [];
  const rng = mulberry32(20261031);

  const { sunDir } = makeSky(scene);

  scene.fog = new THREE.Fog(0xdc9364, 130, 620);

  const hemi = new THREE.HemisphereLight(0x9dc4ff, 0x4a3524, 0.9);
  scene.add(hemi);

  const sun = new THREE.DirectionalLight(0xffb27a, 2.4);
  sun.position.set(-120, 150, -170);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.near = 1;
  sun.shadow.camera.far = 460;
  sun.shadow.camera.left = -95;
  sun.shadow.camera.right = 95;
  sun.shadow.camera.top = 95;
  sun.shadow.camera.bottom = -95;
  sun.shadow.bias = -0.0004;
  sun.shadow.normalBias = 0.045;
  scene.add(sun);
  const sunTarget = new THREE.Object3D();
  scene.add(sunTarget);
  sun.target = sunTarget;

  const ambient = new THREE.AmbientLight(0xffd9b8, 0.28);
  scene.add(ambient);

  makeMountains(scene);

  // desert floor + asphalt city base
  const desert = new THREE.Mesh(
    new THREE.PlaneGeometry(1900, 1900),
    new THREE.MeshStandardMaterial({ color: 0x8a6a4c, roughness: 1 })
  );
  desert.rotation.x = -Math.PI / 2;
  desert.position.y = -0.09;
  desert.receiveShadow = true;
  scene.add(desert);

  const base = new THREE.Mesh(
    new THREE.PlaneGeometry(800, 800),
    new THREE.MeshStandardMaterial({ color: 0x2b2e35, roughness: 0.96 })
  );
  base.rotation.x = -Math.PI / 2;
  base.position.y = -0.02;
  base.receiveShadow = true;
  scene.add(base);

  // road dashes
  const dashGeos = [];
  for (const line of CITY.lines) {
    for (let t = -368; t <= 368; t += 14) {
      if (CITY.lines.some((l) => Math.abs(t - l) < 10)) continue;
      const gv = new THREE.PlaneGeometry(0.34, 5.6);
      gv.rotateX(-Math.PI / 2);
      gv.translate(line, 0.012, t);
      dashGeos.push(gv);
      const gh = new THREE.PlaneGeometry(5.6, 0.34);
      gh.rotateX(-Math.PI / 2);
      gh.translate(t, 0.012, line);
      dashGeos.push(gh);
    }
  }
  const dashMesh = new THREE.Mesh(
    mergeGeometries(dashGeos, false),
    new THREE.MeshStandardMaterial({ color: 0xd8cfa8, roughness: 0.85, emissive: 0x3a321d, emissiveIntensity: 0.25 })
  );
  dashMesh.receiveShadow = true;
  scene.add(dashMesh);

  // sidewalk blocks
  const walkGeos = [];
  const parkGeos = [];
  const blockCenters = [];
  for (let i = 0; i < 9; i++) {
    for (let j = 0; j < 9; j++) {
      const cx = -336 + i * 84;
      const cz = -336 + j * 84;
      blockCenters.push([cx, cz]);
      const slab = new THREE.BoxGeometry(66, 0.18, 66);
      slab.translate(cx, 0.07, cz);
      walkGeos.push(slab);
      for (const [sx, sz] of [[-31, -31], [31, -31], [-31, 31], [31, 31], [0, -31], [0, 31], [-31, 0], [31, 0]]) {
        sidewalkPoints.push({ x: cx + sx + (sx === 0 ? rand(-18, 18) : 0), z: cz + sz + (sz === 0 ? rand(-18, 18) : 0) });
      }
    }
  }
  const walkMesh = new THREE.Mesh(
    mergeGeometries(walkGeos, false),
    new THREE.MeshStandardMaterial({ color: 0x9a978f, roughness: 0.95 })
  );
  walkMesh.receiveShadow = true;
  scene.add(walkMesh);

  // facades
  const tex = makeFacadeTextures(4711, anisotropy);
  const wallMaterials = PALETTES.map((color) => new THREE.MeshStandardMaterial({
    color,
    map: tex.facade,
    emissiveMap: tex.emissive,
    emissive: 0xffb15c,
    emissiveIntensity: 0.7,
    roughness: 0.93,
    metalness: 0.02,
  }));
  const wallGeos = PALETTES.map(() => []);
  const trimGeos = [];
  const roofMat = new THREE.MeshStandardMaterial({ color: 0x615f5c, roughness: 0.98 });

  function addBuilding(cx, cz, w, d, h, paletteIndex) {
    const g = windowBox(w, h, d);
    g.translate(cx, h / 2 + 0.16, cz);
    wallGeos[paletteIndex].push(g);

    const roof = new THREE.BoxGeometry(w + 0.5, 0.55, d + 0.5);
    roof.translate(cx, h + 0.42, cz);
    trimGeos.push(roof);

    const plinth = new THREE.BoxGeometry(w + 0.7, 1.15, d + 0.7);
    plinth.translate(cx, 0.72, cz);
    trimGeos.push(plinth);

    if (h > 22 && rng() < 0.5) {
      const ac = new THREE.BoxGeometry(rand(1.2, 2.4), rand(0.6, 1.2), rand(1.2, 2.4));
      ac.translate(cx + rand(-w / 3, w / 3), h + 1.0, cz + rand(-d / 3, d / 3));
      trimGeos.push(ac);
    }
    if (h > 42 && rng() < 0.45) {
      const tank = new THREE.CylinderGeometry(1.25, 1.25, 2.1, 8);
      tank.translate(cx + rand(-w / 3, w / 3), h + 2.4, cz + rand(-d / 3, d / 3));
      trimGeos.push(tank);
    }

    colliders.push({ minX: cx - w / 2 - 0.2, maxX: cx + w / 2 + 0.2, minZ: cz - d / 2 - 0.2, maxZ: cz + d / 2 + 0.2, h });
    buildings.push({ x: cx, z: cz, w, d, h });
  }

  for (const [bx, bz] of blockCenters) {
    const dist = Math.hypot(bx, bz) / 480;
    const centerBoost = Math.pow(Math.max(0, 1 - dist), 1.7);
    const baseH = 9 + 62 * centerBoost;
    const roll = rng();

    if (roll < 0.085) {
      // little park
      const grass = new THREE.BoxGeometry(58, 0.22, 58);
      grass.translate(bx, 0.15, bz);
      parkGeos.push(grass);
      continue;
    }

    if (roll < 0.36) {
      for (const sx of [-1, 1]) {
        for (const sz of [-1, 1]) {
          if (rng() < 0.12) continue;
          const w = rand(22, 25.5);
          const d = rand(22, 25.5);
          const h = baseH * rand(0.55, 1.25) + rand(0, 6);
          addBuilding(bx + sx * 14.5, bz + sz * 14.5, w, d, Math.max(7, h), Math.floor(rng() * PALETTES.length));
        }
      }
    } else if (roll < 0.56) {
      for (const sx of [-1, 1]) {
        const w = rand(22, 25.5);
        const d = rand(48, 54);
        const h = baseH * rand(0.6, 1.3) + rand(0, 8);
        addBuilding(bx + sx * 14.7, bz, w, d, Math.max(8, h), Math.floor(rng() * PALETTES.length));
      }
    } else {
      const w = rand(34, 52);
      const d = rand(34, 52);
      let h = baseH * rand(0.7, 1.35) + rand(0, 10);
      if (rng() < 0.14) h += 28;
      addBuilding(bx, bz, w, d, Math.max(9, h), Math.floor(rng() * PALETTES.length));
    }
  }

  wallGeos.forEach((geos, i) => {
    if (!geos.length) return;
    const mesh = new THREE.Mesh(mergeGeometries(geos, false), wallMaterials[i]);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    scene.add(mesh);
    solidMeshes.push(mesh);
  });

  const trimMesh = new THREE.Mesh(mergeGeometries(trimGeos, false), roofMat);
  trimMesh.castShadow = true;
  trimMesh.receiveShadow = true;
  scene.add(trimMesh);
  solidMeshes.push(trimMesh);

  if (parkGeos.length) {
    const parkMesh = new THREE.Mesh(
      mergeGeometries(parkGeos, false),
      new THREE.MeshStandardMaterial({ color: 0x517a3c, roughness: 1 })
    );
    parkMesh.receiveShadow = true;
    scene.add(parkMesh);
  }

  // palms (instanced)
  const palm = makePalmGeometry();
  const palmCount = 78;
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x7a5533, roughness: 0.95 });
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x3f7d3b, roughness: 0.9, side: THREE.DoubleSide });
  const trunks = new THREE.InstancedMesh(palm.trunk, trunkMat, palmCount);
  const leaves = new THREE.InstancedMesh(palm.leaves, leafMat, palmCount);
  trunks.castShadow = true;
  leaves.castShadow = true;
  trunks.receiveShadow = true;
  const dummy = new THREE.Object3D();
  for (let i = 0; i < palmCount; i++) {
    let p;
    if (i < 60) p = pick(sidewalkPoints);
    else {
      const b = pick(blockCenters);
      p = { x: b[0] + rand(-24, 24), z: b[1] + rand(-24, 24) };
    }
    const s = rand(0.8, 1.35);
    dummy.position.set(p.x, 0.12, p.z);
    dummy.rotation.set(0, rand(0, TAU), 0);
    dummy.scale.set(s, s * rand(0.9, 1.15), s);
    dummy.updateMatrix();
    trunks.setMatrixAt(i, dummy.matrix);
    leaves.setMatrixAt(i, dummy.matrix);
  }
  trunks.instanceMatrix.needsUpdate = true;
  leaves.instanceMatrix.needsUpdate = true;
  scene.add(trunks, leaves);

  // street lights
  const poleGeos = [];
  const lampGeos = [];
  for (const line of CITY.lines) {
    for (let t = -360; t <= 360; t += 48) {
      if (CITY.lines.some((l) => Math.abs(t - l) < 18)) continue;
      // along vertical roads
      poleGeos.push(new THREE.CylinderGeometry(0.11, 0.16, 7, 5).translate(line + 10.5, 3.5, t));
      poleGeos.push(new THREE.BoxGeometry(2.1, 0.14, 0.14).translate(line + 9.5, 6.95, t));
      lampGeos.push(new THREE.BoxGeometry(0.85, 0.18, 0.42).translate(line + 8.6, 6.86, t));
      // along horizontal roads
      poleGeos.push(new THREE.CylinderGeometry(0.11, 0.16, 7, 5).translate(t, 3.5, line + 10.5));
      poleGeos.push(new THREE.BoxGeometry(0.14, 0.14, 2.1).translate(t, 6.95, line + 9.5));
      lampGeos.push(new THREE.BoxGeometry(0.42, 0.18, 0.85).translate(t, 6.86, line + 8.6));
    }
  }
  const poleMesh = new THREE.Mesh(
    mergeGeometries(poleGeos, false),
    new THREE.MeshStandardMaterial({ color: 0x3a3e45, roughness: 0.7, metalness: 0.35 })
  );
  poleMesh.castShadow = true;
  scene.add(poleMesh);
  const lampMesh = new THREE.Mesh(
    mergeGeometries(lampGeos, false),
    new THREE.MeshStandardMaterial({ color: 0xffe0a8, emissive: 0xffb45c, emissiveIntensity: 1.4, roughness: 0.4 })
  );
  scene.add(lampMesh);

  // hydrants & bins
  const hydrantGeos = [];
  const binGeos = [];
  for (let i = 0; i < 44; i++) {
    const p = pick(sidewalkPoints);
    if (i % 2 === 0) {
      hydrantGeos.push(new THREE.CylinderGeometry(0.18, 0.22, 0.75, 6).translate(p.x, 0.55, p.z));
      hydrantGeos.push(new THREE.SphereGeometry(0.2, 6, 5).translate(p.x, 0.95, p.z));
    } else {
      binGeos.push(new THREE.BoxGeometry(0.62, 1.0, 0.62).translate(p.x, 0.68, p.z));
    }
  }
  const hydrantMesh = new THREE.Mesh(
    mergeGeometries(hydrantGeos, false),
    new THREE.MeshStandardMaterial({ color: 0xc23b2b, roughness: 0.7 })
  );
  hydrantMesh.castShadow = true;
  scene.add(hydrantMesh);
  const binMesh = new THREE.Mesh(
    mergeGeometries(binGeos, false),
    new THREE.MeshStandardMaterial({ color: 0x2f4a37, roughness: 0.95 })
  );
  binMesh.castShadow = true;
  scene.add(binMesh);

  // billboards
  for (const b of BILLBOARDS) {
    const bb = makeBillboard(b, anisotropy);
    scene.add(bb);
  }

  // mission spots at intersections
  const missionSpots = [
    { x: -294, z: -126, name: 'GANG SENGKETA' },
    { x: 210, z: 126, name: 'KOTA TUA' },
    { x: -126, z: 294, name: 'PANTAI KREMES' },
    { x: 126, z: -294, name: 'TERMINAL TELUR' },
  ];

  for (const lx of CITY.lines) {
    for (const lz of CITY.lines) {
      intersections.push({ x: lx, z: lz });
    }
  }

  // parked car spots along curbs
  const usedSpots = new Set();
  for (let i = 0; i < 34; i++) {
    const vertical = rng() < 0.5;
    const line = pick(CITY.lines);
    const side = rng() < 0.5 ? -1 : 1;
    const t = rand(-340, 340);
    if (CITY.lines.some((l) => Math.abs(t - l) < 14)) continue;
    const key = `${line.toFixed(0)}:${t.toFixed(0)}:${vertical}`;
    if (usedSpots.has(key)) continue;
    usedSpots.add(key);
    if (vertical) {
      carSpots.push({ x: line + side * 6.4, z: t, heading: side > 0 ? Math.PI : 0 });
    } else {
      carSpots.push({ x: t, z: line + side * 6.4, heading: side > 0 ? -Math.PI / 2 : Math.PI / 2 });
    }
  }

  function districtAt(x, z) {
    const ix = Math.max(0, Math.min(2, Math.floor((x + 378) / 252)));
    const iz = Math.max(0, Math.min(2, Math.floor((z + 378) / 252)));
    return DISTRICTS[iz * 3 + ix];
  }

  function randomRoadPoint(minDistFromPlayer = 0, px = 0, pz = 0) {
    for (let tries = 0; tries < 40; tries++) {
      const vertical = rng() < 0.5;
      const line = pick(CITY.lines);
      const t = rand(-340, 340);
      const x = vertical ? line + rand(-4, 4) : t;
      const z = vertical ? t : line + rand(-4, 4);
      if (Math.hypot(x - px, z - pz) < minDistFromPlayer) continue;
      return { x, z, vertical };
    }
    return { x: 0, z: 0, vertical: true };
  }

  return {
    colliders,
    buildings,
    solidMeshes,
    sidewalkPoints,
    carSpots,
    intersections,
    missionSpots,
    districtAt,
    randomRoadPoint,
    sun,
    sunTarget,
    sunDir,
    playHalf: CITY.playHalf,
    lines: CITY.lines,
  };
}

import * as THREE from 'three';
import { makeLabelSprite, rand, TAU, clamp } from './utils.js';

const materialCache = new Map();
function mat(color, opts = {}) {
  const key = color + '|' + JSON.stringify(opts);
  if (!materialCache.has(key)) {
    materialCache.set(key, new THREE.MeshStandardMaterial({
      color,
      roughness: opts.roughness ?? 0.82,
      metalness: opts.metalness ?? 0.05,
      flatShading: opts.flatShading ?? false,
      emissive: opts.emissive ?? 0x000000,
      emissiveIntensity: opts.emissiveIntensity ?? 1,
      transparent: opts.transparent ?? false,
      opacity: opts.opacity ?? 1,
      side: opts.side ?? THREE.FrontSide,
    }));
  }
  return materialCache.get(key);
}

const FEATHER = 0xf3e6cf;
const FEATHER_2 = 0xdcc9a7;
const COMB = 0xd92f24;
const BEAK = 0xf0a02a;
const LEG = 0xe08a2e;
const TAIL = 0x17634f;

export function createRooster() {
  const root = new THREE.Group();
  const bodyGroup = new THREE.Group();
  bodyGroup.position.y = 1.12;
  root.add(bodyGroup);

  const bodyMat = mat(FEATHER, { roughness: 0.95 });
  const body = new THREE.Mesh(new THREE.SphereGeometry(1, 18, 14), bodyMat);
  body.scale.set(0.62, 0.56, 0.86);
  body.castShadow = true;
  bodyGroup.add(body);

  const breast = new THREE.Mesh(new THREE.SphereGeometry(1, 14, 10), mat(FEATHER_2, { roughness: 0.95 }));
  breast.scale.set(0.5, 0.48, 0.42);
  breast.position.set(0, -0.06, 0.45);
  breast.castShadow = true;
  bodyGroup.add(breast);

  // neck
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.28, 0.42, 8), bodyMat);
  neck.position.set(0, 0.34, 0.52);
  neck.rotation.x = 0.42;
  neck.castShadow = true;
  bodyGroup.add(neck);

  const headGroup = new THREE.Group();
  headGroup.position.set(0, 0.47, 0.64);
  bodyGroup.add(headGroup);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.35, 16, 12), bodyMat);
  head.castShadow = true;
  headGroup.add(head);

  const combMat = mat(COMB, { roughness: 0.6, emissive: 0x4a0804, emissiveIntensity: 0.35 });
  for (let i = 0; i < 3; i++) {
    const c = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.24 - i * 0.03, 0.2), combMat);
    c.position.set(0, 0.34 + (i === 1 ? 0.03 : 0), -0.12 + i * 0.14);
    c.rotation.z = i === 0 ? -0.15 : i === 2 ? 0.15 : 0;
    c.castShadow = true;
    headGroup.add(c);
  }

  const beak = new THREE.Mesh(new THREE.ConeGeometry(0.14, 0.42, 5), mat(BEAK, { roughness: 0.55 }));
  beak.rotation.x = Math.PI / 2;
  beak.position.set(0, -0.01, 0.38);
  beak.castShadow = true;
  headGroup.add(beak);

  const wattle = new THREE.Mesh(new THREE.SphereGeometry(1, 8, 6), mat(COMB, { roughness: 0.6 }));
  wattle.scale.set(0.11, 0.19, 0.12);
  wattle.position.set(0, -0.28, 0.27);
  headGroup.add(wattle);

  const eyeMat = mat(0x111111, { roughness: 0.3, metalness: 0.1 });
  const eyeGlint = mat(0xffffff, { emissive: 0xffffff, emissiveIntensity: 0.5 });
  for (const sx of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.062, 8, 6), eyeMat);
    eye.position.set(sx * 0.17, 0.09, 0.27);
    headGroup.add(eye);
    const glint = new THREE.Mesh(new THREE.SphereGeometry(0.022, 6, 4), eyeGlint);
    glint.position.set(sx * 0.19, 0.12, 0.315);
    headGroup.add(glint);
  }

  // wings
  const wingL = new THREE.Group();
  const wingR = new THREE.Group();
  wingL.position.set(-0.6, 0.1, 0.02);
  wingR.position.set(0.6, 0.1, 0.02);
  const wingGeo = new THREE.SphereGeometry(1, 8, 6);
  const wl = new THREE.Mesh(wingGeo, mat(FEATHER_2, { roughness: 0.95 }));
  wl.scale.set(0.13, 0.42, 0.6);
  wl.position.set(0, -0.2, 0);
  wl.castShadow = true;
  wingL.add(wl);
  const wr = wl.clone();
  wingR.add(wr);
  bodyGroup.add(wingL, wingR);

  // tail feathers
  const tail = new THREE.Group();
  tail.position.set(0, 0.25, -0.72);
  const tailMat = mat(TAIL, { roughness: 0.45, metalness: 0.35, emissive: 0x063026, emissiveIntensity: 0.6 });
  for (let i = 0; i < 5; i++) {
    const f = new THREE.Mesh(new THREE.ConeGeometry(0.1, 1.15, 4), tailMat);
    f.position.set(0, 0.1, 0);
    f.rotation.set(-0.8 - i * 0.04, (i - 2) * 0.2, (i - 2) * 0.17);
    f.castShadow = true;
    tail.add(f);
  }
  bodyGroup.add(tail);

  // legs
  const legMat = mat(LEG, { roughness: 0.7 });
  const legL = new THREE.Group();
  const legR = new THREE.Group();
  for (const [grp, sx] of [[legL, -1], [legR, 1]]) {
    grp.position.set(sx * 0.21, 0.72, 0.02);
    const shin = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.05, 0.62, 6), legMat);
    shin.position.y = -0.31;
    shin.castShadow = true;
    grp.add(shin);
    const foot = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.09, 0.42), legMat);
    foot.position.set(0, -0.62, 0.11);
    foot.castShadow = true;
    grp.add(foot);
    root.add(grp);
  }

  root.userData = {
    bodyGroup, headGroup, wingL, wingR, tail, legL, legR, body, phase: 0,
    update(dt, opts = {}) {
      const { speed = 0, grounded = true, sprint = false, attack = 0, time = 0 } = opts;
      const u = root.userData;
      u.phase += dt * (2.0 + speed * 2.5);
      const amp = Math.min(1, speed / 5.5) * 0.95;
      u.legL.rotation.x = Math.sin(u.phase) * amp;
      u.legR.rotation.x = -Math.sin(u.phase) * amp;
      u.bodyGroup.position.y = 1.12 + Math.abs(Math.sin(u.phase * 2)) * 0.055 * amp;
      u.bodyGroup.rotation.x = attack * 0.22;
      u.bodyGroup.rotation.z = Math.sin(u.phase) * 0.04 * amp;
      u.headGroup.position.z = 0.64 + attack * 0.22;
      u.headGroup.position.y = 0.47 + Math.sin(u.phase * 2) * 0.02 * amp;
      u.headGroup.rotation.x = Math.sin(u.phase * 2) * 0.05 * amp + attack * 1.05;
      u.tail.rotation.x = Math.sin(u.phase * 0.7) * 0.07 + (sprint ? -0.08 : 0);
      u.tail.rotation.y = Math.sin(u.phase * 0.45) * 0.09;

      let flare = 0.03;
      if (!grounded) flare = 0.9 + Math.sin(time * 26) * 0.28;
      else if (sprint) flare = 0.42;
      u.wingL.rotation.z = flare;
      u.wingR.rotation.z = -flare;
      if (!grounded) {
        u.legL.rotation.x = 0.7;
        u.legR.rotation.x = 0.45;
      }
    },
  };
  return root;
}

const SHIRTS = [0x3f7fbf, 0xc4563f, 0x4f8a54, 0xd1a43a, 0x7b5aa6, 0xd7d2c4, 0x2f6f70, 0xc76b8d];
const PANTS = [0x2e3742, 0x3d4a5c, 0x4b4035, 0x2b2b2b, 0x5c5a55];
const SKINS = [0xe0b089, 0xc48a5f, 0x8d5a3a, 0xf0c9a0, 0x6e452c];

export function createHuman(role = 'ped') {
  const root = new THREE.Group();
  const skin = role === 'cop' ? 0xd9a97e : SKINS[Math.floor(Math.random() * SKINS.length)];
  const shirtColor = role === 'cop' ? 0x243a63 : role === 'gang' ? 0x8f1f24 : SHIRTS[Math.floor(Math.random() * SHIRTS.length)];
  const pantsColor = role === 'cop' ? 0x1b2a45 : PANTS[Math.floor(Math.random() * PANTS.length)];
  const shirtMat = mat(shirtColor);
  const pantsMat = mat(pantsColor);
  const skinMat = mat(skin, { roughness: 0.85 });
  const shoeMat = mat(0x1c1c1c, { roughness: 0.9 });

  const torso = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.72, 0.31), shirtMat);
  torso.position.y = 1.24;
  torso.castShadow = true;
  root.add(torso);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.225, 12, 10), skinMat);
  head.position.y = 1.79;
  head.castShadow = true;
  root.add(head);

  const hairMat = mat(role === 'gang' ? 0x2b1a12 : 0x231a16, { roughness: 0.95 });
  if (role === 'cop') {
    const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.245, 0.245, 0.13, 10), mat(0x14233d));
    cap.position.y = 1.97;
    cap.castShadow = true;
    root.add(cap);
    const brim = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.05, 0.2), mat(0x0e1a2e));
    brim.position.set(0, 1.93, 0.19);
    root.add(brim);
    const badge = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.1, 0.02), mat(0xffc531, { emissive: 0x5a3c00, emissiveIntensity: 0.5 }));
    badge.position.set(-0.17, 1.36, 0.17);
    root.add(badge);
  } else {
    const hair = new THREE.Mesh(new THREE.SphereGeometry(0.235, 12, 8, 0, TAU, 0, Math.PI * 0.55), hairMat);
    hair.position.y = 1.81;
    root.add(hair);
    if (role === 'gang') {
      const band = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.1, 0.46), mat(0xc31d1d));
      band.position.y = 1.86;
      root.add(band);
    }
  }

  const armGeo = new THREE.BoxGeometry(0.14, 0.64, 0.17);
  const armL = new THREE.Group();
  const armR = new THREE.Group();
  armL.position.set(-0.37, 1.53, 0);
  armR.position.set(0.37, 1.53, 0);
  const al = new THREE.Mesh(armGeo, shirtMat);
  al.position.y = -0.3;
  al.castShadow = true;
  armL.add(al);
  const ar = al.clone();
  armR.add(ar);
  const handL = new THREE.Mesh(new THREE.SphereGeometry(0.085, 6, 5), skinMat);
  handL.position.y = -0.66;
  armL.add(handL);
  const handR = handL.clone();
  armR.add(handR);
  root.add(armL, armR);

  const legGeo = new THREE.BoxGeometry(0.19, 0.78, 0.22);
  const legL = new THREE.Group();
  const legR = new THREE.Group();
  legL.position.set(-0.15, 0.88, 0);
  legR.position.set(0.15, 0.88, 0);
  const ll = new THREE.Mesh(legGeo, pantsMat);
  ll.position.y = -0.39;
  ll.castShadow = true;
  legL.add(ll);
  const lr = ll.clone();
  legR.add(lr);
  const shoeL = new THREE.Mesh(new THREE.BoxGeometry(0.21, 0.11, 0.32), shoeMat);
  shoeL.position.set(0, -0.78, 0.05);
  legL.add(shoeL);
  const shoeR = shoeL.clone();
  legR.add(shoeR);
  root.add(legL, legR);

  if (role === 'gang') {
    const strap = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.62, 0.05), mat(0x2b1a12));
    strap.position.set(0.12, 1.26, 0.18);
    strap.rotation.z = 0.5;
    root.add(strap);
  }

  root.userData = {
    role, armL, armR, legL, legR, torso, head, phase: Math.random() * TAU,
    update(dt, speed = 0) {
      const u = root.userData;
      u.phase += dt * (1.4 + speed * 2.4);
      const amp = clamp(speed / 4.2, 0, 1) * 0.75;
      u.legL.rotation.x = Math.sin(u.phase) * amp;
      u.legR.rotation.x = -Math.sin(u.phase) * amp;
      u.armL.rotation.x = -Math.sin(u.phase) * amp * 0.85;
      u.armR.rotation.x = Math.sin(u.phase) * amp * 0.85;
      u.torso.position.y = 1.24 + Math.abs(Math.sin(u.phase * 2)) * 0.025 * amp;
    },
  };
  return root;
}

const CAR_TYPES = {
  sedan: { w: 1.92, l: 4.3, bodyH: 0.54, cabW: 1.66, cabH: 0.5, cabL: 1.95, cabZ: -0.12, wheel: 0.37 },
  sport: { w: 1.98, l: 4.5, bodyH: 0.44, cabW: 1.62, cabH: 0.4, cabL: 1.75, cabZ: -0.24, wheel: 0.36 },
  van: { w: 2.05, l: 4.9, bodyH: 0.72, cabW: 1.86, cabH: 0.62, cabL: 2.7, cabZ: -0.2, wheel: 0.4 },
  police: { w: 1.96, l: 4.4, bodyH: 0.5, cabW: 1.68, cabH: 0.5, cabL: 2.0, cabZ: -0.12, wheel: 0.37 },
};

const CAR_COLORS = [0xc23b32, 0x2f6fb5, 0xd9a62e, 0x4d8f5b, 0xdedad0, 0x373c46, 0x8b4fa0, 0x2f8f8f, 0xd96a2f];

export function createCar(opts = {}) {
  const type = opts.type || 'sedan';
  const d = CAR_TYPES[type] || CAR_TYPES.sedan;
  const color = opts.color ?? (opts.police ? 0xe8e6df : CAR_COLORS[Math.floor(Math.random() * CAR_COLORS.length)]);
  const root = new THREE.Group();
  const paint = mat(color, { roughness: 0.38, metalness: 0.35 });
  const dark = mat(0x1b1e24, { roughness: 0.6, metalness: 0.2 });
  const glass = mat(0x1c2a38, { roughness: 0.12, metalness: 0.7, emissive: 0x0a141e, emissiveIntensity: 0.4 });

  const body = new THREE.Mesh(new THREE.BoxGeometry(d.w, d.bodyH, d.l), paint);
  body.position.y = 0.5;
  body.castShadow = true;
  body.receiveShadow = true;
  root.add(body);

  const skirt = new THREE.Mesh(new THREE.BoxGeometry(d.w + 0.04, 0.2, d.l - 0.2), dark);
  skirt.position.y = 0.31;
  root.add(skirt);

  const cab = new THREE.Mesh(new THREE.BoxGeometry(d.cabW, d.cabH, d.cabL), glass);
  cab.position.set(0, 0.5 + d.bodyH / 2 + d.cabH / 2 - 0.03, d.cabZ);
  cab.castShadow = true;
  root.add(cab);

  const roof = new THREE.Mesh(new THREE.BoxGeometry(d.cabW + 0.02, 0.1, d.cabL - 0.16), paint);
  roof.position.set(0, 0.5 + d.bodyH / 2 + d.cabH + 0.01, d.cabZ);
  roof.castShadow = true;
  root.add(roof);

  const bumperF = new THREE.Mesh(new THREE.BoxGeometry(d.w + 0.06, 0.18, 0.22), dark);
  bumperF.position.set(0, 0.42, d.l / 2 - 0.02);
  root.add(bumperF);
  const bumperR = bumperF.clone();
  bumperR.position.z = -d.l / 2 + 0.02;
  root.add(bumperR);

  const lightMat = new THREE.MeshStandardMaterial({ color: 0xfff0c0, emissive: 0xffe0a0, emissiveIntensity: 1.6 });
  const tailMat = new THREE.MeshStandardMaterial({ color: 0xff3322, emissive: 0xff1408, emissiveIntensity: 1.1 });
  for (const sx of [-1, 1]) {
    const hl = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.16, 0.06), lightMat);
    hl.position.set(sx * 0.62, 0.58, d.l / 2 + 0.01);
    root.add(hl);
    const tl = new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.14, 0.06), tailMat);
    tl.position.set(sx * 0.64, 0.6, -d.l / 2 - 0.01);
    root.add(tl);
  }

  const wheelGeo = new THREE.CylinderGeometry(d.wheel, d.wheel, 0.26, 12);
  wheelGeo.rotateZ(Math.PI / 2);
  const hubGeo = new THREE.CylinderGeometry(d.wheel * 0.42, d.wheel * 0.42, 0.28, 8);
  hubGeo.rotateZ(Math.PI / 2);
  const wheelMat = mat(0x14161a, { roughness: 0.95 });
  const hubMat = mat(0xa8a8a8, { roughness: 0.4, metalness: 0.8 });
  const wheels = [];
  for (const sx of [-1, 1]) {
    for (const sz of [1, -1]) {
      const w = new THREE.Group();
      w.position.set(sx * (d.w / 2 - 0.08), d.wheel, sz * (d.l / 2 - 0.72));
      const tire = new THREE.Mesh(wheelGeo, wheelMat);
      tire.castShadow = true;
      w.add(tire);
      const hub = new THREE.Mesh(hubGeo, hubMat);
      w.add(hub);
      root.add(w);
      wheels.push(w);
    }
  }

  let lightbar = null;
  if (opts.police) {
    const stripe = new THREE.Mesh(new THREE.BoxGeometry(d.w + 0.03, 0.2, 1.4), mat(0x1b2f5c));
    stripe.position.set(0, 0.55, 0.1);
    root.add(stripe);
    const barBase = new THREE.Mesh(new THREE.BoxGeometry(1.15, 0.1, 0.26), dark);
    barBase.position.set(0, 0.5 + d.bodyH / 2 + d.cabH + 0.09, d.cabZ);
    root.add(barBase);
    const redMat = new THREE.MeshStandardMaterial({ color: 0xff2b2b, emissive: 0xff0000, emissiveIntensity: 2.4 });
    const blueMat = new THREE.MeshStandardMaterial({ color: 0x2b6bff, emissive: 0x0033ff, emissiveIntensity: 2.4 });
    const red = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.16, 0.22), redMat);
    red.position.set(-0.3, 0.5 + d.bodyH / 2 + d.cabH + 0.19, d.cabZ);
    root.add(red);
    const blue = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.16, 0.22), blueMat);
    blue.position.set(0.3, 0.5 + d.bodyH / 2 + d.cabH + 0.19, d.cabZ);
    root.add(blue);
    lightbar = { red, blue, redMat, blueMat };
  }

  root.userData = { wheels, lightbar, type, color };
  return root;
}

export function createPickup(type) {
  const root = new THREE.Group();
  if (type === 'cash') {
    for (let i = 0; i < 3; i++) {
      const bill = new THREE.Mesh(
        new THREE.BoxGeometry(0.7, 0.05, 0.36),
        mat(0x3f8f4a, { roughness: 0.6, emissive: 0x0d2a10, emissiveIntensity: 0.5 })
      );
      bill.position.y = i * 0.06;
      bill.rotation.y = i * 0.3;
      root.add(bill);
    }
    const band = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.16, 0.38), mat(0xd9b23a, { roughness: 0.5 }));
    band.position.y = 0.06;
    root.add(band);
  } else if (type === 'health') {
    const box = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.62, 0.62), mat(0xf0eee6, { roughness: 0.6 }));
    box.position.y = 0.2;
    root.add(box);
    const red = mat(0xd42f2f, { emissive: 0x4a0505, emissiveIntensity: 0.4 });
    const c1 = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.14, 0.66), red);
    c1.position.y = 0.2;
    root.add(c1);
    const c2 = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.42, 0.66), red);
    c2.position.y = 0.2;
    root.add(c2);
  } else {
    const box = new THREE.Mesh(new THREE.BoxGeometry(0.66, 0.42, 0.46), mat(0x4a5a33, { roughness: 0.8 }));
    box.position.y = 0.2;
    root.add(box);
    const lid = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.1, 0.5), mat(0x2f3a20));
    lid.position.y = 0.46;
    root.add(lid);
    for (let i = 0; i < 3; i++) {
      const bullet = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.28, 6), mat(0xd9b23a, { metalness: 0.7, roughness: 0.3 }));
      bullet.rotation.z = Math.PI / 2;
      bullet.position.set(-0.18 + i * 0.18, 0.55, 0);
      root.add(bullet);
    }
  }
  root.userData.baseY = 0.6;
  root.userData.update = (time) => {
    root.rotation.y = time * 1.7;
    root.position.y = root.userData.baseY + Math.sin(time * 2.4 + root.position.x) * 0.16;
  };
  return root;
}

export function createMarker(color = 0xffc531, label = 'MISI', scale = 1) {
  const root = new THREE.Group();
  const c = new THREE.Color(color);
  const ringMat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, toneMapped: false });
  const ring = new THREE.Mesh(new THREE.TorusGeometry(2.3 * scale, 0.1 * scale, 6, 40), ringMat);
  ring.rotation.x = -Math.PI / 2;
  ring.position.y = 0.12;
  root.add(ring);

  const beamMat = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 0.16, side: THREE.DoubleSide,
    depthWrite: false, blending: THREE.AdditiveBlending, toneMapped: false,
  });
  const beam = new THREE.Mesh(new THREE.CylinderGeometry(2.05 * scale, 2.25 * scale, 7, 24, 1, true), beamMat);
  beam.position.y = 3.5;
  root.add(beam);

  const gemMat = new THREE.MeshStandardMaterial({
    color: c.clone().offsetHSL(0, 0, 0.15), emissive: color, emissiveIntensity: 1.4,
    roughness: 0.2, metalness: 0.4,
  });
  const gem = new THREE.Mesh(new THREE.OctahedronGeometry(0.5 * scale, 0), gemMat);
  gem.position.y = 4.1;
  root.add(gem);

  const sprite = makeLabelSprite(label, { border: '#' + c.getHexString(), color: '#fff6d8', scale: 0.72 * scale });
  sprite.position.y = 5.5 * scale;
  root.add(sprite);

  root.userData.update = (time) => {
    gem.rotation.y = time * 1.4;
    gem.position.y = 4.1 + Math.sin(time * 2) * 0.18;
    beamMat.opacity = 0.12 + Math.sin(time * 2.2) * 0.04;
    ring.scale.setScalar(1 + Math.sin(time * 2.2) * 0.025);
  };
  return root;
}

