Now the big one: game.js.

Let me carefully plan all systems and code.

### Setup
```js
import * as THREE from 'three';
import { buildWorld, CITY } from './world.js';
import { createRooster, createHuman, createCar, createPickup, createMarker } from './models.js';
import { Sound } from './audio.js';
import { clamp, damp, dampAngle, angleDiff, rand, randInt, pick, TAU, makeCanvasTexture } from './utils.js';

const canvas = document.getElementById('game');
const renderer = new THREE.WebGLRenderer({canvas, antialias:true, powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.75));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
