function spawnTrafficCar() {
  const axis = Math.random()<.5?'x':'z';
  const line = pick(world.lines);
  const dir = Math.random()<.5?1:-1;
  const t = rand(-360,360);
  const x = axis==='x'? t : line - dir*4.5;
  const z = axis==='z'? t : line - dir*4.5;
  const heading = axis==='x' ? (dir>0?Math.PI/2:-Math.PI/2) : (dir>0?0:Math.PI);
  const car = makeVehicle({x,z,heading,type:pick(['sedan','sport','van']),traffic:true,axis,line,dir,baseSpeed:rand(6,10)});
  car.speed=car.baseSpeed;
