function shoot() {
  if (state.mode!=='playing' || player.dead || state.driving) return;
  if (state.weapon!=='pistol') { punch(); return; }
  if (state.ammo<=0) { sound.click(); notify('Amunisi habis!', 'bad'); state.shootCd=.5; return; }
  state.ammo--; state.shootCd=.24; setAmmoUI();
