  player.attackT=.22;
  cameraShake = Math.max(cameraShake, .18);
  const origin = new THREE.Vector3(player.pos.x, 1.55, player.pos.z);
  const dir = new THREE.Vector3(); camera.getWorldDirection(dir); dir.normalize();
  // wall hit
  ray.set(origin, dir); ray.far = 70;
  const wallHits = ray.intersectObjects(world.solidMeshes,false);
  let maxDist = wallHits.length ? wallHits[0].distance : 70;
  // find target
  let best=null, bestT=maxDist;
  for npc of npcs alive:
    const v = new Vector3(npc.pos.x, 1.1, npc.pos.z).sub(origin);
    const t = v.dot(dir);
    if (t<0 || t>maxDist) continue;
    const perp = v.addScaledVector(dir, -t).length(); // careful v mutated; clone
    if (perp < 1.1 + t*0.025 && t < bestT) { best=npc; bestT=t; }
  // cars
  let bestCar=null;
  for cars: v at car pos y .8; similar perp<2.2.
  let end;
  if (best) { end = npc chest; damageNpc(best, 38); }
  else if (bestCar) { end = car pos y .8; damageCar(bestCar, 14); }
  else end = origin + dir*maxDist;
  spawnTracer(muzzlePos, end);
  spawnMuzzleFlash(muzzlePos);
}
