const scorchTex = makeCanvasTexture(128, 128, (ctx, w, h) => {
  const g = ctx.createRadialGradient(w / 2, h / 2, 2, w / 2, h / 2, w / 2);
  g.addColorStop(0, 'rgba(10,8,6,.92)');
  g.addColorStop(0.55, 'rgba(18,14,10,.72)');
