function addPickup(type, x, z, value = 0, permanent = false) {
  const group = createPickup(type);
  group.position.set(x, 0.6, z);
  group.userData.baseY = 0.6;
  scene.add(group);
  const p = { group, type, x, z, active: true, respawn: permanent ? Infinity : 0, value };
  pickups.push(p);
