import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const out = '/home/runner/work/PlayGround/PlayGround/screenshots'
mkdirSync(out, { recursive: true })

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.setDefaultTimeout(30000)
const errors = []
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR:', e.message) })
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE:', m.text()) })

await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => document.fonts.status === 'loaded')
await page.waitForTimeout(800)
await page.click('#start-btn')
await page.waitForTimeout(1200)

const step = async (name, fn, wait = 1200) => {
  console.log('STEP:', name)
  try { await fn() } catch (e) { console.log('ERR', name, e.message) }
  await page.waitForTimeout(wait)
  await page.screenshot({ path: join(out, name + '.png') })
}

// 1. Delivery mission: start, teleport to car, enter, drive
await step('test-01-delivery-start', async () => {
  await page.evaluate(() => {
    const r = window.__rooster
    r.mission('delivery')
  })
  await page.waitForTimeout(400)
  const info = await page.evaluate(() => {
    const r = window.__rooster
    const m = r.getMission()
    return { car: m && m.car ? { x: m.car.pos.x, z: m.car.pos.z } : null, player: { x: r.player.pos.x, z: r.player.pos.z } }
  })
  console.log('mission info', JSON.stringify(info))
  await page.evaluate(({ x, z }) => window.__rooster.teleport(x + 2, z + 2), info.car)
  await page.waitForTimeout(300)
  await page.keyboard.press('KeyF')
}, 800)

await step('test-02-driving', async () => {
  await page.keyboard.down('KeyW')
  await page.waitForTimeout(2600)
  await page.keyboard.up('KeyW')
  const s = await page.evaluate(() => {
    const r = window.__rooster
    const m = r.getMission()
    return { driving: !!r.state.driving, phase: m && m.phase, speed: r.state.driving ? r.state.driving.speed : null, car: m && m.car ? { x: Math.round(m.car.pos.x), z: Math.round(m.car.pos.z) } : null, index: m && m.index }
  })
  console.log('driving state', JSON.stringify(s))
}, 500)

// 2. Teleport car to checkpoints to complete mission
await step('test-03-delivery-complete', async () => {
  const res = await page.evaluate(async () => {
    const r = window.__rooster
    const m = r.getMission()
    if (!m) return { error: 'no mission' }
    const log = []
    for (let i = 0; i < m.checkpoints.length; i++) {
      const cp = m.checkpoints[i]
      m.car.pos.x = cp.x; m.car.pos.z = cp.z
      await new Promise((res) => setTimeout(res, 250))
      log.push({ i, index: m.index, done: !r.getMission() })
      if (!r.getMission()) break
    }
    return { log, done: !r.getMission(), money: r.state.money }
  })
  console.log('delivery result', JSON.stringify(res))
}, 1200)

// 3. Wanted level / cops / heli
await step('test-04-wanted', async () => {
  await page.evaluate(() => { window.__rooster.teleport(-40, -40); window.__rooster.stars(4) })
  await page.waitForTimeout(4500)
  const s = await page.evaluate(() => {
    const r = window.__rooster
    return { wanted: r.state.wanted, cops: r.npcs.filter(n => n.type === 'cop').length, heli: !!r.world.heli, npcs: r.npcs.length }
  })
  console.log('wanted state', JSON.stringify(s))
}, 800)

// 4. Shooting
await step('test-05-shoot', async () => {
  await page.evaluate(() => window.__rooster.stars(0))
  await page.waitForTimeout(500)
  await page.mouse.move(720, 450)
  await page.mouse.down()
  await page.waitForTimeout(900)
  await page.mouse.up()
  await page.keyboard.press('Space')
  await page.waitForTimeout(500)
