import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 900, height: 600 } })
page.on('pageerror', (e) => console.log('PAGEERROR:', e.message))
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForTimeout(800)
await page.click('#start-btn')
await page.waitForTimeout(800)

// enter any car near rampage: find closest vehicle to player after teleport to mission
const enter = await page.evaluate(() => {
  const r = window.__rooster
  r.teleport(210, 126)
  r.mission('rampage')
  const m = r.getMission()
  // find nearest car to mission, teleport player next to it
  let best = null, bd = 1e9
  for (const v of r.vehicles) { if (v.dead) continue; const d = Math.hypot(v.pos.x - 210, v.pos.z - 126); if (d < bd) { bd = d; best = v } }
  r.teleport(best.pos.x + 1, best.pos.z + 1)
  return { npcs: m.spawned.map(n => ({ x: n.pos.x, z: n.pos.z, alive: n.alive })), car: { x: best.pos.x, z: best.pos.z, type: best.type } }
})
console.log('rampage setup', JSON.stringify(enter))
await page.waitForTimeout(300)
await page.keyboard.press('KeyF')
await page.waitForTimeout(1500)
console.log('drv', JSON.stringify(await page.evaluate(() => ({ drv: !!window.__rooster.state.driving }))))

const rampage = await page.evaluate(async () => {
  const r = window.__rooster
  const m = r.getMission()
  const log = []
  const targets = m.spawned.map(n => ({ n, x: n.pos.x, z: n.pos.z }))
  for (const t of targets) {
    const mm = r.getMission()
    if (!mm) { log.push('done'); break }
    const car = r.state.driving
    car.pos.x = t.x; car.pos.z = t.z; car.speed = 18
    await new Promise(res => setTimeout(res, 900))
    log.push({ kills: r.getMission() ? r.getMission().kills : 'done', alive: t.n.alive, money: r.state.money })
    if (!r.getMission()) break
  }
  return { log, done: !r.getMission(), money: r.state.money }
})
console.log('rampage', JSON.stringify(rampage))
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/test-rampage.png' })

// hit mission
await page.waitForTimeout(1500)
const hit = await page.evaluate(async () => {
  const r = window.__rooster
  r.teleport(-126, 294)
  r.mission('hit')
  const m = r.getMission()
  const target = m.target
  // find car
  let best = null, bd = 1e9
  for (const v of r.vehicles) { if (v.dead) continue; const d = Math.hypot(v.pos.x - target.pos.x, v.pos.z - target.pos.z); if (d < bd) { bd = d; best = v } }
  r.teleport(best.pos.x + 1, best.pos.z + 1)
  return { target: { x: target.pos.x, z: target.pos.z, hp: target.health }, car: { x: best.pos.x, z: best.pos.z } }
})
console.log('hit setup', JSON.stringify(hit))
await page.waitForTimeout(300)
await page.keyboard.press('KeyF')
await page.waitForTimeout(1500)
const hitres = await page.evaluate(async () => {
  const r = window.__rooster
  const m = r.getMission()
  if (!m) return { noMission: true }
  const t = m.target
  const car = r.state.driving
  const log = []
  if (!car) return { noCar: true }
  car.pos.x = t.pos.x; car.pos.z = t.pos.z; car.speed = 20
  for (let i = 0; i < 6; i++) {
    await new Promise(res => setTimeout(res, 900))
    log.push({ alive: t.alive, hp: t.health, done: !r.getMission(), money: r.state.money })
    if (!r.getMission()) break
    const mm = r.getMission()
    if (!mm) break
    car.pos.x = mm.target.pos.x; car.pos.z = mm.target.pos.z; car.speed = 20
  }
  return { log, done: !r.getMission(), money: r.state.money }
})
console.log('hit', JSON.stringify(hitres))
