import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 900, height: 600 } })
page.on('pageerror', (e) => console.log('PAGEERROR:', e.message))
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForTimeout(800)
await page.click('#start-btn')
await page.waitForTimeout(800)

// rampage: enter car first
await page.evaluate(() => {
  const r = window.__rooster
  r.teleport(210, 126)
  let best = null, bd = 1e9
  for (const v of r.vehicles) { if (v.dead) continue; const d = Math.hypot(v.pos.x - 210, v.pos.z - 126); if (d < bd) { bd = d; best = v } }
  r.teleport(best.pos.x + 1, best.pos.z + 1)
})
await page.waitForTimeout(300)
await page.keyboard.press('KeyF')
await page.waitForTimeout(1200)
const ramp = await page.evaluate(async () => {
  const r = window.__rooster
  r.teleport(210, 126)
  r.mission('rampage')
  const m = r.getMission()
  const car = r.state.driving
  if (!car) return { noCar: true }
  const targets = m.spawned.slice()
  const log = []
  for (const n of targets) {
    if (!n.alive) { log.push('already'); continue }
    for (let k = 0; k < 4 && n.alive; k++) {
      n.pos.x = car.pos.x; n.pos.z = car.pos.z
      car.speed = 20
      await new Promise(res => setTimeout(res, 500))
    }
    log.push({ alive: n.alive, kills: r.getMission() ? r.getMission().kills : 'done' })
    if (!r.getMission()) break
  }
  return { log, done: !r.getMission(), money: r.state.money }
})
console.log('rampage', JSON.stringify(ramp))
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/test-rampage2.png' })

// hit mission
await page.waitForTimeout(1200)
const setup = await page.evaluate(() => {
  const r = window.__rooster
  r.teleport(-126, 294)
  r.mission('hit')
  const m = r.getMission()
  return { has: !!m, target: m && m.target ? { x: m.target.pos.x, z: m.target.pos.z } : null, driving: !!r.state.driving }
})
console.log('hit setup', JSON.stringify(setup))
const hitres = await page.evaluate(async () => {
  const r = window.__rooster
  const m = r.getMission()
  if (!m || !m.target) return { noMission: true }
  const t = m.target
  const car = r.state.driving
  if (!car) return { noCar: true }
  const log = []
  for (let i = 0; i < 8; i++) {
    const mm = r.getMission()
    if (!mm) { log.push('done'); break }
    if (!mm.target.alive) { log.push('dead'); break }
    t.pos.x = car.pos.x; t.pos.z = car.pos.z
    car.speed = 20
    await new Promise(res => setTimeout(res, 500))
    log.push({ alive: t.alive, done: !r.getMission(), money: r.state.money })
  }
  return { log, done: !r.getMission(), money: r.state.money }
})
console.log('hit', JSON.stringify(hitres))
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/test-hit.png' })
await browser.close()

