import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const out = '/home/runner/work/PlayGround/PlayGround/screenshots'
mkdirSync(out, { recursive: true })
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const errors = []
const bad = []
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.setDefaultTimeout(30000)
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR:', e.message) })
page.on('response', (r) => { if (r.status() >= 400) { bad.push(r.status() + ' ' + r.url()); console.log('HTTP', r.status(), r.url()) } })
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => document.fonts.status === 'loaded')
await page.waitForTimeout(1200)
await page.screenshot({ path: join(out, 'final-menu.png') })
console.log('menu captured')

await page.click('#start-btn')
await page.waitForTimeout(2000)
await page.screenshot({ path: join(out, 'final-start.png') })
console.log('start captured')

// delivery driving
await page.evaluate(() => {
  const r = window.__rooster
  r.teleport(-126, -42)
  r.mission('delivery')
  const c = r.getMission().car
  r.teleport(c.pos.x + 1.5, c.pos.z + 1.5)
})
await page.waitForTimeout(600)
await page.keyboard.press('KeyF')
await page.waitForTimeout(2000)
await page.keyboard.down('KeyW')
await page.waitForTimeout(7000)
await page.screenshot({ path: join(out, 'final-driving.png') })
await page.keyboard.up('KeyW')
const drv = await page.evaluate(() => {
  const r = window.__rooster; const m = r.getMission()
  return { driving: !!r.state.driving, phase: m && m.phase, speed: m && Math.round(m.car.speed * 10) / 10, kmh: m && Math.round(Math.abs(m.car.speed) * 3.6) }
})
console.log('driving', JSON.stringify(drv))

// wanted + cops + heli
await page.evaluate(() => {
  const r = window.__rooster
  r.teleport(42, 42)
  r.stars(5)
})
await page.waitForTimeout(18000)
const wanted = await page.evaluate(() => {
  const r = window.__rooster
  const heli = r.scene.children.find(c => c.type === 'Group' && c.position.y > 20 && c.children.length >= 7)
  // face nearest cop
  let cop = null, bd = 1e9
  for (const n of r.npcs) if (n.role === 'cop' && n.alive) { const d = Math.hypot(n.pos.x - r.player.pos.x, n.pos.z - r.player.pos.z); if (d < bd) { bd = d; cop = n } }
  if (cop) r.cam.yaw = Math.atan2(cop.pos.x - r.player.pos.x, cop.pos.z - r.player.pos.z)
  return {
    wanted: r.state.wanted, points: Math.round(r.state.wantedPoints),
    cops: r.npcs.filter(n => n.role === 'cop' && n.alive).length,
    copDist: cop ? Math.round(bd) : null,
    heli: heli ? { x: Math.round(heli.position.x), y: Math.round(heli.position.y), z: Math.round(heli.position.z) } : null,
    health: Math.round(r.player.health),
  }
})
console.log('wanted', JSON.stringify(wanted))
await page.waitForTimeout(1000)
await page.screenshot({ path: join(out, 'final-wanted.png') })

// death + respawn
await page.evaluate(() => window.__rooster.hurt(500))
await page.waitForTimeout(1200)
await page.screenshot({ path: join(out, 'final-death.png') })
const deathVisible = await page.evaluate(() => !document.getElementById('death-screen').classList.contains('hidden'))
console.log('death visible', deathVisible)
await page.click('#respawn-btn')
await page.waitForTimeout(1500)
const resp = await page.evaluate(() => { const r = window.__rooster; return { health: r.player.health, money: r.state.money, wanted: r.state.wanted, mode: r.state.mode, x: Math.round(r.player.pos.x), z: Math.round(r.player.pos.z) } })
console.log('respawn', JSON.stringify(resp))
await page.screenshot({ path: join(out, 'final-respawn.png') })

// rampage complete to check pageerror fix
const ramp = await page.evaluate(async () => {
  const r = window.__rooster
  const v = r.vehicles.find(v => !v.dead)
  r.teleport(v.pos.x + 1, v.pos.z + 1)
  return { car: { x: v.pos.x, z: v.pos.z } }
})
await page.waitForTimeout(400)
await page.keyboard.press('KeyF')
await page.waitForTimeout(1200)
const rampres = await page.evaluate(async () => {
  const r = window.__rooster
  r.teleport(210, 126)
  r.mission('rampage')
  const m = r.getMission()
  const car = r.state.driving
  if (!m || !car) return { no: true }
  const log = []
  for (const n of m.spawned) {
    if (!n.alive) continue
    for (let k = 0; k < 5 && n.alive; k++) {
      n.pos.x = car.pos.x; n.pos.z = car.pos.z; car.speed = 20
      await new Promise(res => setTimeout(res, 450))
    }
    log.push({ alive: n.alive, done: !r.getMission() })
    if (!r.getMission()) break
  }
  return { log, done: !r.getMission(), money: r.state.money }
})
console.log('rampage', JSON.stringify(rampres))

// mobile
const mp = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true })
mp.on('pageerror', (e) => { errors.push('mobile: ' + e.message); console.log('MOBILE PAGEERROR:', e.message) })
await mp.goto('http://localhost:3002', { waitUntil: 'load' })
await mp.waitForTimeout(1200)
await mp.click('#start-btn')
await mp.waitForTimeout(2500)
await mp.screenshot({ path: join(out, 'final-mobile.png') })
console.log('mobile captured')

console.log('ERRORS', JSON.stringify(errors))
console.log('BAD', JSON.stringify(bad))
await browser.close()

