const cash = types.find(p => p.type === 'cash')
const health = types.find(p => p.type === 'health')
const ammo = types.find(p => p.type === 'ammo')
const collect = async (p, before) => {
  await page.evaluate(({ x, z }) => window.__rooster.teleport(x, z), p)
  await page.waitForTimeout(1000)
  return page.evaluate(() => ({ money: window.__rooster.state.money, health: Math.round(window.__rooster.player.health), ammo: window.__rooster.state.ammo }))
}
const c0 = await page.evaluate(() => ({ money: window.__rooster.state.money, health: Math.round(window.__rooster.player.health), ammo: window.__rooster.state.ammo }))
console.log('before', JSON.stringify(c0))
console.log('cash', JSON.stringify(await collect(cash)))
await page.evaluate(() => window.__rooster.setHealth(40))
console.log('health', JSON.stringify(await collect(health)))
console.log('ammo', JSON.stringify(await collect(ammo)))

// kill ped -> wanted
const wantedBefore = await page.evaluate(() => window.__rooster.state.wanted)
const ped = await page.evaluate(() => {
  const r = window.__rooster
  const p = r.npcs.find(n => n.role === 'ped' && n.alive)
  if (!p) return null
  r.teleport(p.pos.x + 2, p.pos.z + 2)
  return { x: p.pos.x, z: p.pos.z }
})
await page.waitForTimeout(500)
const killed = await page.evaluate(() => {
  const r = window.__rooster
  const p = r.npcs.find(n => n.role === 'ped' && n.alive)
  if (!p) return null
