.tbtn.big { width: 70px; height: 70px; grid-column: span 2; justify-self: end; background: rgba(190,42,32,.72); border-color: rgba(255,160,140,.6); }

/* ---------- Overlays ---------- */
.overlay {
  position: fixed; inset: 0; z-index: 30; display: flex;
  background: linear-gradient(100deg, rgba(6,8,12,.92) 0%, rgba(6,8,12,.72) 48%, rgba(6,8,12,.35) 100%);
}
#start-screen { padding: calc(5vh + var(--safe-t)) 5vw calc(4vh + var(--safe-b)); flex-direction: column; justify-content: center; }
.title-wrap { max-width: 780px; }
.eyebrow {
  display: inline-flex; align-items: center; gap: 9px; margin-bottom: 14px;
  font: 700 13px/1 'Barlow Condensed'; letter-spacing: .32em; color: var(--gold);
}
.eyebrow::before { content: ''; width: 32px; height: 2px; background: var(--gold); }
h1 {
  margin: 0; font: 400 clamp(58px, 11vw, 148px)/0.82 'Anton', Impact, sans-serif;
  letter-spacing: .01em; text-transform: uppercase;
  color: #fff; text-shadow: 0 4px 0 #b4441d, 0 10px 38px rgba(0,0,0,.6);
}
h1 .city {
  display: block; color: transparent;
  -webkit-text-stroke: 3px var(--gold);
  text-shadow: 0 0 34px rgba(255,170,30,.38);
  letter-spacing: .06em;
}
.tagline {
  margin: 22px 0 0; max-width: 560px; font: 600 22px/1.25 'Barlow Condensed';
  color: rgba(255,255,255,.82); letter-spacing: .02em;
}
.tagline b { color: var(--gold); font-weight: 700; }
.start-actions { margin-top: 30px; display: flex; align-items: center; gap: 18px; flex-wrap: wrap; }
